def semver_sort(versions):
    def parse_key(v):
        core = v
        pre = None
        if '+' in core:
            core = core.split('+', 1)[0]
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        if pre is None:
            pre_key = None
        else:
            ids = pre.split('.')
            pre_key = []
            for ident in ids:
                if ident.isdigit():
                    pre_key.append((0, int(ident), ''))
                else:
                    pre_key.append((1, 0, ident))
        return (major, minor, patch, pre is None, pre_key)

    def cmp(a, b):
        ka = parse_key(a)
        kb = parse_key(b)
        if ka[0] != kb[0]: return ka[0]-kb[0]
        if ka[1] != kb[1]: return ka[1]-kb[1]
        if ka[2] != kb[2]: return ka[2]-kb[2]
        # pre-release presence: version without pre-release (True) sorts after (False)
        if ka[3] != kb[3]:
            return -1 if not ka[3] else 1
        if ka[3] and kb[3]:
            return 0
        pa, pb = ka[4], kb[4]
        for x, y in zip(pa, pb):
            if x != y:
                if x[0] != y[0]:
                    return x[0]-y[0]
                if x[0] == 0:
                    return x[1]-y[1]
                else:
                    return -1 if x[2] < y[2] else (1 if x[2] > y[2] else 0)
        return len(pa) - len(pb)

    import functools
    return sorted(versions, key=functools.cmp_to_key(cmp))

